};

/*Fonction d'écriture dans la propriété WEEKLY_SCHEDULE de l'objet schedule avec l'ID saisi en paramètre.*/
function writePropertyAsync(address, objectId, propertyId, value, options) {
    return new Promise((resolve, reject) => {
        try {
            client.writeProperty(
                address,
                objectId,
                propertyId,
                value,
                options,
                (err, value) => {
                    if (err) {
                        reject(err);
                    } else {
                        resolve(value);
                    }
                }
            );
        } catch (err) {
            reject(err);
        }
    });
}
/*Récupération des évenements traités par le node "InterpretSchedule" */
let BACNetWeeklySchedulePayload = msg.payload;

await writePropertyAsync(
    address, 
    {
        type: bacnet.ObjectType.SCHEDULE,
        instance: Number(currentSchedule.scheduleid)
    },
    bacnet.PropertyIdentifier.WEEKLY_SCHEDULE,
    BACNetWeeklySchedulePayload, 
    {}

);
client.close();

