/* Interprete et traite les informations reçues par le node "Get Room Calendar" */

const schedules = flow.get('schedulesParameters');
const currentSchedule = schedules[msg.nbr];
const events = msg.payload;
const nbrEvents = events.length;
const valueType = currentSchedule.valuetype;

if (events.length === 0) {
    node.warn('No events to process');
    let weeklySchedule =
        [
            [],
            [],
            [],
            [],
            [],
            [],
            [],
        ]
    msg.payload = weeklySchedule;
    node.send(msg);
}

/* Ajoute un nombre d'heures souahité "h" a un objet de type Date, peut ètre negatif  */
function addHours(date, h) {
    return new Date(new Date(date).getTime() + (h * 60 * 60 * 1000));
}

/* Ajoute un nombre de minutes souahité "m" a un objet de type Date, peut ètre negatif */
function addMinutes(date, m) {
    return new Date(new Date(date).getTime() + (m * 60 * 1000));
}

/* Tableau dans lequel les évènements vont etre placés, une liste par jour de la semaine.*/
let weeklySchedule = [
    [],
    [],
    [],
    [],
    [],
    [],
    []
];

/* Tableau permettant de connaitre le nombre d'évenements par jour de la semaine.*/
let dailyEventsCounter = [
    0,
    0,
    0,
    0,
    0,
    0,
    0,
];
/*Création des évènements, chaque évènement est construit a partir de deux horraires : début et fin*/
node.warn(nbrEvents + " events to process")
for (let i = 0; i < nbrEvents; i++) {

    /*Récupération des paramètres saisis dans le node "TO CONFIGURE"*/
    const evt = events[i];

    /*Ajout du décalage horraire UTC */
    const date = addHours(evt.eventStart, flow.get("UTCoffset") || 0);
    /*Décalage lié au temps de préchauffe saisi en paramètre */
    const timestart = addMinutes(addHours(evt.eventStart, flow.get("UTCoffset") || 0), -currentSchedule.preheattime);
    /*Décalage lié au temps d'inertie saisi en paramètre */
    const timeend = addMinutes(addHours(evt.eventEnd, flow.get("UTCoffset") || 0), -currentSchedule.inertiatime);
    /*Création date de début d'évènement*/
    let dateStart = new Date;
    dateStart.setFullYear(date.getFullYear());
    dateStart.setMonth(date.getMonth());
    dateStart.setDate(date.getDate());
    dateStart.setHours(timestart.getHours());
    dateStart.setMinutes(timestart.getMinutes());
    dateStart.setSeconds(timestart.getSeconds())
    dateStart.setMilliseconds(timestart.getMilliseconds())
    weeklySchedule[(date.getDay() + 6) % 7][dailyEventsCounter[(date.getDay() + 6) % 7]] = {
        time: {
            type: bacnet.ApplicationTag.TIME,
            value: dateStart
        },
        value: {
            /*Type saisi en paramètre*/
            type: valueType,
            /*Valeur saisie en paramètre*/
            value: currentSchedule.occupiedvalue
        }
    }
    /*Index le lundi en premier jour de la semaine, le get room calendar ayant le dimanche en premier indice*/
    dailyEventsCounter[(date.getDay() + 6) % 7] = dailyEventsCounter[(date.getDay() + 6) % 7] + 1;

    /*Création date de fin d'évènement*/
    let dateEnd = new Date;
    dateEnd.setFullYear(date.getFullYear());
    dateEnd.setMonth(date.getMonth());
    dateEnd.setDate(date.getDate());
    dateEnd.setHours(timeend.getHours());
    dateEnd.setMinutes(timeend.getMinutes());
    dateEnd.setSeconds(timeend.getSeconds())
    dateEnd.setMilliseconds(timeend.getMilliseconds())
    weeklySchedule[(date.getDay() + 6) % 7][dailyEventsCounter[(date.getDay() + 6) % 7]] = {
        time: {
            type: bacnet.ApplicationTag.TIME,
            value: dateEnd
        },
        value: {
            /*Type saisi en paramètre*/
            type: valueType,
            /*Valeur saisie en paramètre*/
            value: currentSchedule.defaultvalue
        }
    }
    /*Index le lundi en premier jour de la semaine, le get room calendar ayant le dimanche en premier indice*/
    dailyEventsCounter[(date.getDay() + 6) % 7] = dailyEventsCounter[(date.getDay() + 6) % 7] + 1
}


/*Fusion des évènements si chevauchement de périodes*/

/*Le code parcours les jours j */
for (let j = 0; j < 7; j++) {
    let i = 1;
    node.warn("DAY " + j + " " + weeklySchedule[j].length + " events to filter.");
    /*Pour chaque évenement, on verifie que la fin de l'évenement précédent est anterieur ou égale au début de l'évenement actuel,
    dans le cas contraire, les indice de début de fin se chevauchant sont suprimés.*/
    while (i < weeklySchedule[j].length)
    {  
        if (weeklySchedule[j][i].time.value >= weeklySchedule[j][i-1].time.value)
        {
            i++;
        }
        else
        {
            node.warn("detected events to remove : " + (i-1) + " and " + (i));
            for (let k = i-1; k < (weeklySchedule[j].length-2); k++)
            {
                weeklySchedule[j][k] = weeklySchedule[j][k+2]     
            }
            weeklySchedule[j].pop();
            weeklySchedule[j].pop();
        } 
    }
}
node.warn("dailyEventsCounter = "+ dailyEventsCounter);
/*Transmission au node de communication BACnet */
msg.payload = weeklySchedule;
node.send(msg);

